<?php require '../config/auth.php';login_required('company');$page_title='Applicants';$q=$pdo->prepare('SELECT id FROM companies WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$cid=$q->fetch()['id'];$jid=(int)($_GET['job_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$aid=(int)$_POST['application_id'];$status=$_POST['status'];$q=$pdo->prepare("SELECT a.student_id,j.job_title,s.user_id FROM applications a JOIN jobs j ON j.id=a.job_id JOIN students s ON s.id=a.student_id WHERE a.id=? AND j.company_id=?");$q->execute([$aid,$cid]);$a=$q->fetch();if($a){$pdo->prepare('UPDATE applications SET status=? WHERE id=?')->execute([$status,$aid]);notify($a['user_id'],'Application update','Your application for '.$a['job_title'].' is now '.str_replace('_',' ',$status).'.');flash('Application status updated.');}go('applicants.php'.($jid?'?job_id='.$jid:''));}$sql='SELECT a.*,s.full_name,s.course,s.cgpa,s.skills,s.resume,j.job_title FROM applications a JOIN students s ON s.id=a.student_id JOIN jobs j ON j.id=a.job_id WHERE j.company_id=?';$p=[$cid];if($jid){$sql.=' AND j.id=?';$p[]=$jid;}$sql.=' ORDER BY a.applied_at DESC';$q=$pdo->prepare($sql);$q->execute($p);$rows=$q->fetchAll();require '../config/header.php';flashes();?><div class="head"><div><h1>Applicants</h1><p>Review candidates and update recruitment stages.</p></div></div><div class="card tablewrap"><table class="table"><tr><th>Student</th><th>Course</th><th>CGPA</th><th>Skills</th><th>Job</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['course'])?></td><td><?=e($r['cgpa'])?></td><td><?=e($r['skills'])?></td><td><?=e($r['job_title'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><form method="post" style="display:flex;gap:5px"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="application_id" value="<?=$r['id']?>"><select class="control" name="status"><option>under_review</option><option>shortlisted</option><option>interview_scheduled</option><option>selected</option><option>rejected</option></select><button class="btn primary sm">Update</button></form><?php if($r['resume']):?><a class="small" target="_blank" href="../<?=e($r['resume'])?>">View Resume</a><?php endif;?></td></tr><?php endforeach;?></table><?php if(!$rows):?><div class="empty">No applicants yet.</div><?php endif;?></div><?php require '../config/footer.php';?>
